import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.7F0gE-aX.js";const u=JSON.parse('{"title":"Model tomography","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tomography.md","filePath":"reference/tomography.md","lastUpdated":null}'),o={name:"reference/tomography.md"};function n(r,e,c,d,l,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<blockquote><p><strong>Historical API:</strong> this page describes a removed tomography interface and is retained for migration reference. It is not part of the current supported API. Use <a href="./../user_guide/calibration">calibration</a> for current gate fitting.</p></blockquote><h1 id="Model-tomography" tabindex="-1">Model tomography <a class="header-anchor" href="#Model-tomography" aria-label="Permalink to &quot;Model tomography {#Model-tomography}&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Measurement</span></span>
<span class="line"><span>SequenceData</span></span>
<span class="line"><span>ModelTomographyProblem</span></span>
<span class="line"><span>predict_sequence</span></span>
<span class="line"><span>predict_sequences</span></span>
<span class="line"><span>reconstructed_model</span></span>
<span class="line"><span>tomography_residuals</span></span>
<span class="line"><span>physical_parameters</span></span></code></pre></div><h2 id="Data-and-losses" tabindex="-1">Data and losses <a class="header-anchor" href="#Data-and-losses" aria-label="Permalink to &quot;Data and losses {#Data-and-losses}&quot;">​</a></h2><p>Sequence prediction uses plain sequences and shared settings:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">observed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> predict_sequences</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(target, sequences; preparation, measurement)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">problem </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ModelTomographyProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(initial, paths;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sequences, preparation, measurement, observed, gates</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">initial</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gates)</span></span></code></pre></div><p><code>observed</code> is one probability vector per sequence, ordered by measurement outcome. For integer counts, use <code>counts=measured_counts</code> instead; do not provide both. <code>shots</code> can be a shared positive integer or a vector matching the sequences. Vector entries may be <code>nothing</code>; mixed shot qualification requires explicit <code>loss=:least_squares</code>. Counts infer totals and check any supplied shots. <code>predict_sequence(model, sequence; preparation, measurement)</code> handles one sequence. Prediction requires no observed distributions. Retain <code>SequenceData</code> and the three-argument problem constructor for per-experiment preparation or measurement. Do not mix scalar <code>predict</code> with <code>sequences</code>.</p><p>Scalar fitting uses <code>ModelTomographyProblem(model, paths; predict, observed, uncertainty=1)</code>. <code>observed</code> must be a nonempty NamedTuple. <code>predict(model)</code> is called once per evaluation and must return a NamedTuple with exactly the same names; ordering may differ. Each value must be a finite real scalar. Residuals follow the observation order.</p><p><code>uncertainty</code> is a common nonnegative scalar, or a NamedTuple with one nonnegative uncertainty for every observation. For example, use <code>uncertainty=(ge=0.001, ef=0.002)</code> with <code>observed=(ge=4.8, ef=4.6)</code>. Zero uncertainty leaves that observation unweighted; it does not impose an exact equality constraint. Thus <code>uncertainty=0.0</code> gives unweighted least squares, like the default of 1. Predictions, observations, and uncertainties must use the same units; errors are independent. <code>loss=:auto</code> and <code>:least_squares</code> both minimize uncertainty-scaled residuals.</p><p>For <code>SequenceData</code>, counts infer their shot total. Probabilities may include <code>shots</code> without rounding into reconstructed counts. Keep observations in the measurement&#39;s outcome order; labels are not array indices. <code>loss=:auto</code> uses multinomial negative log likelihood when every record carries shots, and unweighted least squares when none does. Mixed shot-qualified records require explicit <code>loss=:least_squares</code>; shot totals do not weight that loss. Likelihood omits parameter-independent constants and uses <code>probability_floor</code> only inside logarithms. Zero-count terms contribute zero.</p><p><code>tomography_residuals(setup, values)</code> is available for least squares; its squared norm equals the objective. Scalar and direct sequence fitting share the two-argument constructor.</p><h2 id="Measurements-and-prediction" tabindex="-1">Measurements and prediction <a class="header-anchor" href="#Measurements-and-prediction" aria-label="Permalink to &quot;Measurements and prediction {#Measurements-and-prediction}&quot;">​</a></h2><p>Use <code>Measurement(effects; labels=..., acts_on=...)</code> for a complete POVM or <code>Measurement(observable; acts_on=...)</code> for eigenspace projectors. Degenerate observable eigenstates share an outcome. Effects must sum to identity; include leakage as additional outcomes. Subsystem indices are one-based and ascending. Preparations can be kets, density matrices, or functions of the candidate model. Measurements can also be functions returning <code>Measurement</code>.</p><p>Fixed states and effects are interpreted in the candidate&#39;s retained component basis. They are not automatically transformed from an external laboratory basis. Use model-dependent functions when physical updates require regenerating them.</p><p><code>predict_sequence</code> needs no observed data. <code>predict_sequences</code> ignores observed distributions and shares each required gate propagator across all records in that call. Gate clocks reset at each gate&#39;s local origin; empty sequences measure the preparation directly. No propagator cache survives between candidates.</p><h2 id="Solver-options" tabindex="-1">Solver options <a class="header-anchor" href="#Solver-options" aria-label="Permalink to &quot;Solver options {#Solver-options}&quot;">​</a></h2><p>Bounds such as <code>lb</code> and <code>ub</code> go to <code>ModelTomographyProblem</code>; select an optimizer that supports them. Optimizer settings and callbacks go to <code>solve</code>. The wrapper returns the native SciML solution. Automatic differentiation through physical reconstruction is not guaranteed; derivative-free optimization is a useful start.</p><p><code>threaded=true</code> builds gate propagators concurrently. Shared controls and solver callbacks must be safe for concurrent calls. <code>evolution_kwargs</code> forwards native ODE solver settings. Both options affect sequence fits only. Selected slash paths must refer to distinct writable scalar inputs; aliases and overlapping paths are rejected. Inspect solver retcodes, held-out predictions, other initial guesses, and dressed-state tracking confidence before accepting a fit. Low loss does not establish unique parameter recovery.</p><h2 id="Projected-sequence-fitting" tabindex="-1">Projected sequence fitting <a class="header-anchor" href="#Projected-sequence-fitting" aria-label="Permalink to &quot;Projected sequence fitting {#Projected-sequence-fitting}&quot;">​</a></h2><p>Supply <code>subspace</code> as an ordered orthonormal ket vector or a function returning one for the candidate model, for example:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subspace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">states[label] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> label </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ModelTomographyProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, data, paths;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subspace, leakage_outcome</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, threaded</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Only the selected columns are integrated in the full Hamiltonian. The projected gate matrices are cached once per candidate and multiplied to evaluate sequences. The preparation must lie in the supplied basis. Projection after each gate loses paths that leave the basis and later return; compare against full-space predictions and enlarge the basis when needed. This option applies to sequence fits only.</p><p><code>leakage_outcome</code> is a one-based index into each measurement&#39;s ordered effects. That effect must be the complement of the subspace projector. Discarded probability is assigned to this absorbing outcome without conditioning on survival. Without it, appreciable discarded probability raises an error. <code>predict_sequence</code> and <code>predict_sequences</code> accept the same keywords. The default <code>subspace=nothing</code> retains full-space evolution.</p><h2 id="Parameter-normalization" tabindex="-1">Parameter normalization <a class="header-anchor" href="#Parameter-normalization" aria-label="Permalink to &quot;Parameter normalization {#Parameter-normalization}&quot;">​</a></h2><p>Fits default to dimensionless optimizer coordinates, with <code>physical = initial + scale .* coordinates</code>. Initial coordinates are zero; scales are absolute initial parameter values, or 1 for zero-valued parameters. Use <code>parameter_scales=[...]</code> in path order to set characteristic changes, or <code>scale_function=(path, initial) -&gt; ...</code>. Scales must be finite and positive and are fixed for the entire fit. Choose an explicit scale for small shifts starting at zero. Parameter scaling does not change observation uncertainty weights.</p><p><code>solution.u</code>, residual inputs, and reconstruction inputs are optimizer coordinates. Use <code>physical_parameters(setup, solution.u)</code> to report physical values. Bounds <code>lb</code> and <code>ub</code> are supplied in physical units and transformed for the optimizer. Set <code>normalize=false</code> to use physical coordinates directly. Optimizer simplex sizes and coordinate tolerances use the chosen coordinates; objective tolerances such as <code>g_abstol</code> keep their existing meaning.</p><p>Component reconstruction uses <code>threaded_components=true</code> by default in both tomography constructors, independently of <code>threaded</code> gate propagation. Changed component constructors run concurrently when multiple components change and Julia has multiple threads. The normal builder assembles operators and tracks dressed states using the requested reference and intermediate steps. Use <code>threaded_components=false</code> for serial reconstruction or custom constructors that are not thread-safe. Start Julia with <code>--threads=auto</code> to enable workers.</p><p>With <code>normalize_probabilities=false</code>, full-space prediction corrects small state-normalization drift (at most <code>1e-6</code>) after each gate, preventing accumulation when a numerical propagator is reused many times. Larger per-gate errors raise an error asking for tighter evolution tolerances. Projected-subspace leakage is never normalized away.</p><p>Use <code>normalize_probabilities=true</code> in prediction or sequence tomography to normalize finite, nonnegative predicted outcome weights. Projected missing population is assigned to the complementary leakage outcome first, preserving physical leakage. Projected loss without a leakage outcome still raises an error, as do negative weights beyond rounding tolerance, non-finite weights, or zero total weight. The default <code>false</code> retains strict normalization checks. This differs from <code>normalize</code>, which scales optimization parameters. Probability normalization does not correct integration errors in relative phases or outcome proportions.</p><h2 id="Reconstruction-and-state-references" tabindex="-1">Reconstruction and state references <a class="header-anchor" href="#Reconstruction-and-state-references" aria-label="Permalink to &quot;Reconstruction and state references {#Reconstruction-and-state-references}&quot;">​</a></h2><p>Every physical candidate uses <code>make_model</code>, without an incremental reconstruction cache. Tomography defaults to <code>reference_model=:initial, tracking_steps=0</code>: one candidate diagonalization, matched to the fixed initial eigenbasis. Transmon basis maps carry overlaps into the same physical charge basis after EC/EJ changes. Reference states are not frozen and energies always come from the candidate. <code>tracking_steps=N</code> adds N intermediate models along numeric parameter changes; model structure must stay fixed. Confidence is accumulated squared physical overlap along this path; it is not a correctness probability. Inspect it and increase steps near avoided crossings. Candidate evaluation order has no effect. Automatic initial references fall back to bare tracking when basis transport is unavailable; incompatible explicit references raise an error.</p><p>Use <code>reference_model=nothing, tracking_steps=18</code> for the original bare tracking. Normal <code>make_model</code> builds default to that bare trajectory, and accept <code>reference_model=initial, tracking_steps=0</code> for a direct reference match.</p><p>Physical rebuilding does not inherit gates. Pass <code>gates=baseline.gates</code> explicitly to sequence fitting and, when needed, prediction. Gate-only updates reuse idle physics; selected gate-parameter paths are explicit updates and remain supported. Use the keyword <code>Component(name; variables, parameters, operators, operator_generators, hamiltonian, ...)</code> constructor when extending operators. The symbolic operator and numerical generator maps must have matching local string keys.</p><h3 id="Timing-sequence-fits" tabindex="-1">Timing sequence fits <a class="header-anchor" href="#Timing-sequence-fits" aria-label="Permalink to &quot;Timing sequence fits {#Timing-sequence-fits}&quot;">​</a></h3><p>Pass <code>diagnostics=report -&gt; ...</code> to <code>ModelTomographyProblem</code> or <code>predict_sequences</code> to receive timings in seconds after each successful prediction:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reports </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add this keyword to your sequence ModelTomographyProblem call:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># diagnostics = report -&gt; push!(reports, report)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># After evaluating or solving:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># reports[end]</span></span></code></pre></div><p>A sequence fit report contains <code>rebuild_seconds</code>, <code>gate_update_seconds</code>, <code>setup_seconds</code> (sequence inputs and subspace), <code>propagation_seconds</code> (all gate builds), <code>gate_seconds</code> (gate-name =&gt; seconds pairs), <code>sequence_seconds</code> (sequence multiplication and measurements), <code>total_seconds</code>, and <code>parameters</code> (in physical units). Direct <code>predict_sequences</code> reports omit rebuilding, gate updates, and parameters. The total excludes the reporting callback and loss reduction. Initial constructor validation also produces a report. First-call timings include compilation; compare subsequent evaluations. In threaded runs, individual gate times overlap: compare their wall-clock <code>propagation_seconds</code> rather than summing <code>gate_seconds</code>. Reports arrive on the calling task after gate workers finish. Diagnostics are disabled by default; callback errors propagate to the caller.</p>`,37)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
